S = load('input.mat');
f = S.odefun; tspan = S.tspan; y0 = S.y0;
% Route 1: the stated candidate (ode45, solver defaults)
[tA, yA] = ode45(f, tspan, y0);
% Route 2: independent tight implicit solve
opts = odeset('RelTol',1e-12,'AbsTol',1e-14);
[tB, yB] = ode15s(f, tspan, y0, opts);
% Route 3: analytic truth y = exp(-t)
errA = max(abs(yA(:) - exp(-tA(:))));
errB = max(abs(yB(:) - exp(-tB(:))));
fprintf('ode45 vs analytic max abs err = %.3e\n', errA);
fprintf('ode15s vs analytic max abs err = %.3e\n', errB);
fprintf('y(2) ode45=%.17g  analytic exp(-2)=%.17g\n', yA(end), exp(-2));
% Counterexample: a wrong-but-cleanly-exiting solver (fixed-step explicit Euler, h=0.5)
h = 0.5; n = round(diff(tspan)/h); yE = y0; for k=1:n, yE(k+1) = yE(k) + h*f(tspan(1)+ (k-1)*h, yE(k)); end
fprintf('Euler h=0.5 final=%.17g err=%.3e  (all finite, exit flag would be 0)\n', yE(end), abs(yE(end)-exp(-2)));
% Counterexample 2: right answer from a mis-specified ODE sign
[tC, yC] = ode45(@(t,y) y, tspan, y0);
fprintf('wrong-sign ODE y=+y exits cleanly, y(2)=%.6g (exp(+2)=%.6g)\n', yC(end), exp(2));
